#!/usr/bin/env python3
import sqlite3
import time

DATABASE = "/var/lib/job-queue/jobs.sqlite3"


def connect():
    connection = sqlite3.connect(DATABASE, timeout=30.0, isolation_level=None)
    connection.execute("PRAGMA busy_timeout=30000")
    connection.execute("PRAGMA synchronous=FULL")
    return connection


def complete_one(connection):
    connection.execute("BEGIN IMMEDIATE")
    try:
        row = connection.execute(
            "SELECT id, payload FROM jobs "
            "WHERE status = 'queued' ORDER BY rowid LIMIT 1"
        ).fetchone()
        if row is None:
            connection.execute("ROLLBACK")
            return False

        job_id, payload = row
        result = "processed:" + payload
        connection.execute(
            "UPDATE jobs SET status = 'completed', result = ?, attempts = attempts + 1 "
            "WHERE id = ? AND status = 'queued'",
            (result, job_id),
        )
        connection.execute("COMMIT")
        return True
    except Exception:
        connection.execute("ROLLBACK")
        raise


def main():
    connection = connect()
    try:
        while True:
            if not complete_one(connection):
                time.sleep(0.1)
    finally:
        connection.close()


if __name__ == "__main__":
    main()

